-- SPDX-License-Identifier: GPL-3.0-or-later
-- The hook-point tables from hookpoints.lua: names for the SDK, names and addresses for the core.

local names = require("gen.names")
local header_files = require("gen.header_files")

local M = {}

M.sdk_path = "include/wxl/HookPoints.def"
M.core_path = "src/runtime/HookPoints.def"

local SDK_HEAD = {
  "// SPDX-License-Identifier: GPL-3.0-or-later",
  "// Generated by tools/offsets/gen.lua from tools/offsets/hookpoints.lua: do not edit.",
  "// The hook points an extension attaches to by name, in the core's table order. A name is the",
  "// function's name in wxl/offsets. Define WXL_HOOK_POINT_NAME(name) before including.",
  "",
  "#ifndef WXL_HOOK_POINT_NAME",
  "#error \"define WXL_HOOK_POINT_NAME(name) before including HookPoints.def\"",
  "#endif",
}

local CORE_HEAD = {
  "// SPDX-License-Identifier: GPL-3.0-or-later",
  "// Generated by wxl-sdk tools/offsets/gen.lua from tools/offsets/hookpoints.lua: do not edit.",
  "// The hook points by name and address, in the order of the SDK's wxl/HookPoints.def.",
  "",
  "#ifndef WXL_HOOK_POINT",
  "#error \"define WXL_HOOK_POINT(name, address) before including HookPoints.def\"",
  "#endif",
}

local function copy(list)
  local out = {}
  for i, v in ipairs(list) do out[i] = v end
  return out
end

-- Every declared function by its qualified name in wxl/offsets.
local function functions_by_name(entries)
  local by_name = {}
  for _, it in ipairs(entries) do
    if it.kind == "function" and not it.skip then by_name[names.qualified(it.path, it.id)] = it end
  end
  return by_name
end

-- The SDK's and the core's table texts. `rows` is hookpoints.lua: names, and { section = ... } rows
-- that open a section. A name that is no function, or is listed twice, fails.
function M.render(rows, entries, fail)
  local by_name = functions_by_name(entries)
  local sdk, core = copy(SDK_HEAD), copy(CORE_HEAD)
  local seen = {}
  for _, row in ipairs(rows) do
    if type(row) == "table" then
      sdk[#sdk + 1] = ""
      sdk[#sdk + 1] = "// " .. row.section
      core[#core + 1] = ""
      core[#core + 1] = "// " .. row.section
    else
      local it = by_name[row]
      if not it then fail(2, "hookpoints.lua: '%s' is not a function in wxl/offsets", row) end
      if seen[row] then fail(2, "hookpoints.lua: '%s' is listed twice", row) end
      seen[row] = true
      sdk[#sdk + 1] = string.format("WXL_HOOK_POINT_NAME(\"%s\")", row)
      core[#core + 1] = string.format("WXL_HOOK_POINT(\"%s\", %s)", row, header_files.hex(it.e.at))
    end
  end
  return table.concat(sdk, "\n") .. "\n", table.concat(core, "\n") .. "\n"
end

return M
